def add_md_runs(paragraph, text):
    """解析 **bold** 与 *italic* 标记，写入带格式的 run。"""
    token_re = re.compile(r"(\*\*.+?\*\*|\*.+?\*)")
    for part in token_re.split(text):
        if not part:
            continue
        if part.startswith("**") and part.endswith("**"):
            r = paragraph.add_run(part[2:-2])
            r.bold = True
        elif part.startswith("*") and part.endswith("*") and len(part) > 2:
            r = paragraph.add_run(part[1:-1])
            r.italic = True
        else:
            paragraph.add_run(part)


def add_table(doc, header, rows):
    table = doc.add_table(rows=1 + len(rows), cols=len(header))
    table.style = "Table Grid"
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    for j, htext in enumerate(header):
        cell = table.rows[0].cells[j]
        cell.text = htext
        for p in cell.paragraphs:
            for r in p.runs:
                r.bold = True
    for i, row in enumerate(rows):
        for j, val in enumerate(row):
            table.rows[i + 1].cells[j].text = val
    return table


def _add_figure(doc, path, caption):
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.add_run().add_picture(path, width=Inches(6.2))
    cap = doc.add_paragraph()
    r = cap.add_run(caption)
    r.font.size = Pt(9)


def main():
    doc = Document()
    normal = doc.styles["Normal"]
    normal.font.name = "Times New Roman"
    normal.font.size = Pt(11)

    # 标题
    t = doc.add_paragraph()
    t.alignment = WD_ALIGN_PARAGRAPH.CENTER
    tr = t.add_run("Interpretable Four-Branch Attention Fusion Network for AI-Generated Image Detection")
    tr.bold = True
    tr.font.size = Pt(14)

    # 摘要
    doc.add_heading("Abstract", level=1)
    doc.add_paragraph(ABSTRACT)

    # 关键词
    kw = doc.add_paragraph()
    kw.add_run("Keywords: ").bold = True
    kw.add_run(KEYWORDS)

    # 正文
    for kind, text in BODY:
        if kind == "h1":
            doc.add_heading(text, level=1)
        elif kind == "h2":
            doc.add_heading(text, level=2)
        elif kind == "p":
            add_md_runs(doc.add_paragraph(), text)
        elif kind == "bullet":
            add_md_runs(doc.add_paragraph(style="List Bullet"), text)
        elif kind == "eq":
            p = doc.add_paragraph()
            p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            p.add_run(text).italic = True
        elif kind == "table_caption":
            p = doc.add_paragraph()
            p.add_run(text).bold = True
        elif kind == "table1":
            add_table(doc, TABLE1_HEADER, TABLE1_ROWS)
        elif kind == "table2":
            add_table(doc, TABLE2_HEADER, TABLE2_ROWS)
        elif kind == "figure1":
            _add_figure(doc, FIG_ARCH,
                "Figure 1. Overview of the proposed Four-Branch Attention Fusion Network (FBFN). The CNN and ViT branches capture semantic appearance, while the noise (ELA + SRM) and color (Lab + entropy) branches capture physically interpretable low-level artifacts; each produces a pixel-level evidence map. The four maps are fused by a channel-and-spatial dual attention module and globally pooled to an image-level real/fake score.")
        elif kind == "figure2":
            _add_figure(doc, FIG_EVIDENCE,
                "Figure 2. Per-branch evidence maps for one real (top) and one generated (bottom) image. Each branch outputs a single-channel forgery-probability map (warm color = higher likelihood of forgery); the fused map combines all four. The noise and color branches highlight residual and color-statistics artifacts that are not visible in the RGB input, making the decision inspectable.")

    # 参考文献
    for i, ref in enumerate(REFERENCES, 1):
        p = doc.add_paragraph()
        p.add_run(f"[{i}] ").bold = True
        p.add_run(ref)

    doc.save(OUT)
    print(f"已生成 {OUT}")


if __name__ == "__main__":
    main()
